#!/usr/bin/env node
/**
 * Tier 2 curados: macrociclo 06 (25 rutas, mapas 1733–1933) y macrociclo 07
 * (10 rutas, mapas 1940–2015). Completan las 120 rutas Tier 2 de Atlas Mil.
 *
 * Voces: sectores 29–40 de `content/atlas_narrative_seeds.json` (Bahía Relámpago
 * hasta Umbral Mil), con los ejes de crossover ya aprobados. Cada NPC conserva
 * motivación, conflicto, error reconocido y líneas propias; las parejas Pokémon
 * se citan con su nombre de presentación y no como un símbolo de datos.
 */
import fs from "node:fs";
import path from "node:path";
import { ROOT } from "./lib/fire_ash_registry.mjs";

const sentence = (text) => /[.!?…]$/.test(text) ? text : `${text}.`;
function N(name, sprite, role, partner, partnerName, want, error, before, after) {
  return {
    name, sprite, role, partnerPokemon: partner,
    motivation: sentence(`Quiere ${want}`),
    conflict: sentence(`Su error anterior fue que ${error}`),
    dialogue: { before: before.map(sentence), after: after.map(sentence) },
    partnerName,
  };
}
const R = (mapId, title, promise, objective, mechanic, npcs, decision, consequence, reward) => ({ mapId, title, promise, objective, mechanic, npcs, decision, consequence, reward });

