const all = [...specs06, ...specs07];
if (specs06.length !== 25) throw new Error(`Se esperaban 25 rutas en macro06 y hay ${specs06.length}.`);
if (specs07.length !== 10) throw new Error(`Se esperaban 10 rutas en macro07 y hay ${specs07.length}.`);

const banned = /soy un entrenador|qué gran combate|este pokémon es muy fuerte|según la pokédex|debes derrotarme/i;
for (const spec of all) for (const npc of spec.npcs) {
  if (!npc.partnerName) throw new Error(`${spec.mapId}: falta nombre de presentación de ${npc.name}`);
  const lines = [...npc.dialogue.before, ...npc.dialogue.after];
  if (lines.some((line) => banned.test(line))) throw new Error(`${spec.mapId}: frase genérica en ${npc.name}`);
  if (lines.length !== 6) throw new Error(`${spec.mapId}: ${npc.name} necesita 3+3 líneas`);
}

function compileSpec(spec, globalIndex) {
  const flag = 833 + globalIndex;
  const variable = 229 + globalIndex;
  const [mechanicName, rules, failureSafe] = spec.mechanic;
  const [question, options] = spec.decision;
  const [item, meaning] = spec.reward;
  const [immediate, later] = [spec.consequence, spec.npcs.map((npc) => npc.dialogue.after[2])];
  return {
    tier: 2,
    routeBatch: 18 + Math.floor(globalIndex / 5),
    mapId: spec.mapId,
    flag,
    variable,
    title: spec.title,
    promise: sentence(spec.promise),
    objective: sentence(spec.objective),
    mechanic: { name: mechanicName, rules: rules.map(sentence), failureSafe: sentence(failureSafe) },
    npcs: spec.npcs.map((npc) => ({
      name: npc.name,
      sprite: npc.sprite,
      role: npc.role,
      partnerPokemon: npc.partnerPokemon,
      motivation: npc.motivation,
      conflict: npc.conflict,
      dialogue: npc.dialogue,
    })),
    decision: {
      question: sentence(question),
      options,
      immediate: immediate.map(sentence),
      later: later.map(sentence),
    },
    reward: { item, meaning: sentence(meaning) },
    progression: { switchId: flag, decisionVariable: variable, freeReturnMapId: 1001 },
    safety: { bagAlwaysAvailable: true, noForcedBattle: true, existingChallengePreserved: true, baseChallengeExpected: false, freeReturn: true, rewardOnce: true },
  };
}

for (const [macroCycle, offset, specs] of [[6, 0, specs06], [7, 25, specs07]]) {
  const blueprints = specs.map((spec, index) => compileSpec(spec, offset + index));
  const output = { version: 1, macroCycle, tier2Batches: macroCycle === 6 ? 5 : 2, blueprints };
  const target = path.join(ROOT, "content", `atlas_tier2_blueprints_macro${String(macroCycle).padStart(2, "0")}.json`);
  fs.writeFileSync(target, `${JSON.stringify(output, null, 2)}\n`);
  console.log(`Tier 2 macrociclo ${String(macroCycle).padStart(2, "0")}: ${blueprints.length} rutas en ${output.tier2Batches} lotes.`);
}
